"""Generate game/images.rpy from the files the asset pipeline produced."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
GAME = ROOT / "game"
CHARS = GAME / "images" / "chars"
BG = GAME / "images" / "bg"
ITEMS = GAME / "images" / "items"
UI = GAME / "images" / "ui"

HEADER = '''################################################################################
## Image declarations
##
## Generated by tools/gen_images_rpy.py - edit that script, not this file.
## Every PNG below was extracted or composed from the IWAD by
## tools/build_assets.py; see game/wad_manifest.json for provenance.
################################################################################
'''

lines: list[str] = [HEADER]

lines.append("## Backgrounds #################################################################\n")
for path in sorted(BG.glob("*.png")):
    lines.append(f'image bg {path.stem} = "images/bg/{path.name}"')

lines.append("\n## Characters #################################################################\n")
moods = ["neutral", "talk", "angry", "pain", "dead"]
characters = sorted({p.stem.rsplit("_", 1)[0] for p in CHARS.glob("*.png")})
for char in characters:
    for mood in moods:
        path = CHARS / f"{char}_{mood}.png"
        if path.exists():
            lines.append(f'image {char} {mood} = "images/chars/{path.name}"')
    lines.append("")

lines.append("\n## Items ######################################################################\n")
for path in sorted(ITEMS.glob("*.png")):
    lines.append(f'image item {path.stem} = "images/items/{path.name}"')

lines.append("\n## Interface ##################################################################\n")
for path in sorted(UI.glob("*.png")):
    lines.append(f'image ui {path.stem} = "images/ui/{path.name}"')

maps = sorted((GAME / "images" / "maps").glob("*.png"))
lines.append("\n## Level archive ##############################################################\n")
for path in maps:
    lines.append(f'image map {path.stem} = "images/maps/{path.name}"')

out = GAME / "images.rpy"
out.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote {out} ({len(characters)} characters, {len(maps)} maps)")